                        <a href="my-shipments" class="btn btn-outline-secondary">My Shipments</a>
                    </Authorized>
                    <NotAuthorized>
                        <p>Please <a href="Account/Login">log in</a> to manage or view your shipments.</p>
                    </NotAuthorized>
                </AuthorizeView>
            </div>
        </div>
    </div>
</div>

@code {
    private string trackingNumber = string.Empty;
    private bool trackingError;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        trackingError = false;

        var shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
        if (shipment is null)
        {
            trackingError = true;
        }
        else
        {
            Nav.NavigateTo($"track/{shipment.TrackingNumber}");
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await TrackShipment();
    }
}

